create table alert_record (read_flag bit, created_at datetime(6), id bigint not null auto_increment, job_id bigint, owner_id bigint, event varchar(255) not null, job_name varchar(255), level varchar(255) not null, message TEXT not null, primary key (id)) engine=InnoDB;
create table app_user (enabled bit not null, token_version integer, created_at datetime(6), id bigint not null auto_increment, last_login_at datetime(6), last_seen_at datetime(6), updated_at datetime(6), signature varchar(200), avatar_key varchar(255), display_name varchar(255), password_hash varchar(255) not null, username varchar(255) not null, role enum ('ADMIN','OPERATOR','VIEWER') not null, status_preference enum ('ONLINE','AWAY','BUSY','INVISIBLE','OFFLINE'), primary key (id)) engine=InnoDB;
create table audit_log (created_at datetime(6), id bigint not null auto_increment, user_id bigint, action varchar(255) not null, detail TEXT, ip varchar(255), target_id varchar(255), target_type varchar(255), username varchar(255), primary key (id)) engine=InnoDB;
create table control_registry (enabled bit, created_at datetime(6), id bigint not null auto_increment, updated_at datetime(6), category varchar(255) not null, description TEXT, flink_template TEXT, jar_path varchar(255) not null, name varchar(255) not null, param_schema TEXT, type varchar(255) not null, version varchar(255) not null, primary key (id)) engine=InnoDB;
create table data_source_connection (credential_configured bit not null, enabled bit not null, created_at datetime(6) not null, id bigint not null auto_increment, owner_id bigint not null, updated_at datetime(6) not null, version bigint, name varchar(128) not null, owner_name varchar(128) not null, config_json TEXT not null, description TEXT, encrypted_credentials TEXT, type enum ('MYSQL','POSTGRESQL','ORACLE','KAFKA','REDIS','HDFS') not null, primary key (id)) engine=InnoDB;
create table diagnosis_report (created_at datetime(6), id bigint not null auto_increment, job_id bigint, owner_id bigint, job_name varchar(64), source varchar(64), trigger varchar(64), root_cause varchar(1000), evidence varchar(4000), suggestions varchar(4000), packet TEXT, param_fixes TEXT, primary key (id)) engine=InnoDB;
create table job_definition (online bit, online_restart_count integer, parallelism integer, schedule_enabled bit, schedule_max_retries integer, schedule_retries integer, completed_at datetime(6), confirmed_at datetime(6), confirmed_by bigint, created_at datetime(6), id bigint not null auto_increment, last_restart_at datetime(6), next_fire_time datetime(6), online_since datetime(6), owner_id bigint, submitted_at datetime(6), updated_at datetime(6), confirmed_by_name varchar(255), cron_expression varchar(255), dag_json TEXT not null, description TEXT, flink_job_id TEXT, name varchar(255) not null, owner_name varchar(255), webhook_url varchar(255), confirmation_status enum ('NOT_REQUIRED','PENDING','CONFIRMED'), source enum ('MANUAL','AI'), status enum ('DRAFT','SUBMITTED','RUNNING','COMPLETED','FAILED','CANCELLED','WAITING','BLOCKED') not null, primary key (id)) engine=InnoDB;
create table job_dependency (created_at datetime(6), downstream_job_id bigint not null, id bigint not null auto_increment, upstream_job_id bigint not null, primary key (id)) engine=InnoDB;
create table job_log (id bigint not null auto_increment, job_id bigint not null, timestamp datetime(6), level varchar(255) not null, message TEXT not null, primary key (id)) engine=InnoDB;
create table job_version (parallelism integer, version_no integer, created_at datetime(6), id bigint not null auto_increment, job_id bigint not null, dag_json TEXT not null, name TEXT, primary key (id)) engine=InnoDB;
create table schedule_history (id bigint not null auto_increment, job_id bigint, trigger_time datetime(6), flink_job_id varchar(255), job_name varchar(255), message TEXT, status varchar(255), primary key (id)) engine=InnoDB;
create table trend_point (bp float(53) not null, input_rate float(53) not null, output_rate float(53) not null, id bigint not null auto_increment, job_id bigint not null, t bigint not null, status varchar(16), run_key varchar(64), primary key (id)) engine=InnoDB;
create index idx_alert_owner_created on alert_record (owner_id, created_at);
create index idx_alert_read_created on alert_record (read_flag, created_at);
alter table app_user add constraint UK_3k4cplvh82srueuttfkwnylq0 unique (username);
alter table control_registry add constraint UK_8yblpuk6mwnqbmuu0b8eyleun unique (type);
create index idx_data_source_owner on data_source_connection (owner_id);
create index idx_data_source_updated on data_source_connection (updated_at);
alter table data_source_connection add constraint uk_data_source_owner_name unique (owner_id, name);
alter table job_dependency add constraint UK4wo2pt0kstqnldji4x0lu6hi6 unique (upstream_job_id, downstream_job_id);
